package com.sirithree.shopops.admin.benchmark.v1.dataset.stage7a;
import static org.assertj.core.api.Assertions.assertThat; import org.junit.jupiter.api.Test; import java.util.*;
class TaskScaleupReviewStatusTest { @Test void newCasesAreModelReviewedAndHumanQueueRemainsPending() throws Exception { var n=Stage7ATaskDatasetSupport.taskCases().stream().map(Stage7ATaskDatasetSupport.CaseView::benchmarkCase).filter(c->c.caseId.startsWith("stage7a-")).toList(); assertThat(n).hasSize(96); assertThat(n).allSatisfy(c->{assertThat(c.reviewStatus).isEqualTo("MODEL_REVIEWED"); assertThat(c.humanReviewed).isFalse();}); Map<String,Object> q=Stage7ATaskDatasetSupport.objectResource("/benchmark/v1/task/stage7a/task-human-review-queue.json"); @SuppressWarnings("unchecked") List<Map<String,Object>> entries=(List<Map<String,Object>>)q.get("entries"); assertThat(entries).hasSize(50); assertThat(entries).allSatisfy(e->assertThat(e.get("status")).isEqualTo("HUMAN_REVIEW_PENDING")); }}
